function applyLanguage(root=document){$$('[data-t]',root).forEach(el=>{if(!el.dataset.en)el.dataset.en=el.textContent;el.textContent=dict[lang]?.[el.dataset.t]||el.dataset.en});document.documentElement.lang=lang==='hi'?'hi':'en';$('#language-label').textContent=lang==='hi'?'हिन्दी':lang==='hinglish'?'Hinglish':'English';}
