const savedHas=(type,id)=>saved.some(s=>s.type===type&&s.id===id);
const saveBtn=(type,id)=>`<button class="save-button ${savedHas(type,id)?'saved':''}" data-save="${type}" data-id="${esc(id)}" aria-label="${savedHas(type,id)?'Remove saved':'Save'} ${esc(id)}" title="${savedHas(type,id)?'Remove from saved':'Save for later'}" aria-pressed="${savedHas(type,id)}">${icon('bookmark')}</button>`;
